
CREATE TABLE wf_lock (id INTEGER PRIMARY KEY); INSERT INTO wf_lock VALUES (1);
CREATE TABLE wf_clock_event (event_id UUID PRIMARY KEY, employee_id UUID NOT NULL REFERENCES mfg_employee(id), kind VARCHAR(20) NOT NULL, occurred_at TIMESTAMP WITH TIME ZONE NOT NULL, source VARCHAR(120) NOT NULL);
CREATE TABLE wf_attendance (id UUID PRIMARY KEY, employee_id UUID NOT NULL REFERENCES mfg_employee(id), starts_at TIMESTAMP WITH TIME ZONE NOT NULL, ends_at TIMESTAMP WITH TIME ZONE NOT NULL, breaks TEXT NOT NULL, raw_event_ids TEXT NOT NULL, state VARCHAR(16) NOT NULL CHECK(state IN ('DRAFT','APPROVED','SUPERSEDED')), overtime_minutes INTEGER NOT NULL CHECK(overtime_minutes>=0), notes VARCHAR(1000) NOT NULL, approved_by VARCHAR(160), replaces_id UUID REFERENCES wf_attendance(id), CHECK(ends_at>starts_at));
CREATE TABLE wf_absence (id UUID PRIMARY KEY, employee_id UUID NOT NULL REFERENCES mfg_employee(id), starts_at TIMESTAMP WITH TIME ZONE NOT NULL, ends_at TIMESTAMP WITH TIME ZONE NOT NULL, kind VARCHAR(16) NOT NULL CHECK(kind IN ('PAID_LEAVE','UNPAID_LEAVE','ABSENCE')), state VARCHAR(16) NOT NULL CHECK(state IN ('DRAFT','APPROVED','CANCELLED')), reason VARCHAR(1000) NOT NULL, approved_by VARCHAR(160), CHECK(ends_at>starts_at));
CREATE TABLE wf_wage (id UUID PRIMARY KEY, employee_id UUID NOT NULL REFERENCES mfg_employee(id), effective_from DATE NOT NULL, basis VARCHAR(12) NOT NULL CHECK(basis IN ('HOURLY','MONTHLY')), amount NUMERIC(19,6) NOT NULL CHECK(amount>0), currency VARCHAR(3) NOT NULL, monthly_minutes INTEGER NOT NULL CHECK(monthly_minutes>=0), UNIQUE(employee_id,effective_from));
CREATE TABLE wf_rule (id UUID PRIMARY KEY, effective_from DATE UNIQUE NOT NULL, night_start TIME NOT NULL, night_end TIME NOT NULL, night_type VARCHAR(12) NOT NULL CHECK(night_type IN ('PERCENT','FIXED')), night_value NUMERIC(19,6) NOT NULL CHECK(night_value>=0), overtime_percent NUMERIC(12,6) NOT NULL CHECK(overtime_percent>=0), stacking VARCHAR(16) NOT NULL CHECK(stacking IN ('ADDITIVE','MULTIPLICATIVE')));
CREATE TABLE wf_period (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, starts_on DATE NOT NULL, ends_on DATE NOT NULL, zone_id VARCHAR(80) NOT NULL, currency VARCHAR(3) NOT NULL, money_scale INTEGER NOT NULL CHECK(money_scale BETWEEN 0 AND 4), state VARCHAR(16) NOT NULL CHECK(state IN ('DRAFT','CALCULATED','DIRTY','REVIEWED','FINALIZED')), calculated_by VARCHAR(160), reviewed_by VARCHAR(160), finalized_by VARCHAR(160), CHECK(ends_on>starts_on));
CREATE TABLE wf_period_employee (period_id UUID REFERENCES wf_period(id), employee_id UUID REFERENCES mfg_employee(id), PRIMARY KEY(period_id,employee_id));
CREATE TABLE wf_adjustment (id UUID PRIMARY KEY, period_id UUID NOT NULL REFERENCES wf_period(id), employee_id UUID NOT NULL REFERENCES mfg_employee(id), kind VARCHAR(12) NOT NULL CHECK(kind IN ('BONUS','DEDUCTION')), amount NUMERIC(19,6) NOT NULL CHECK(amount>0), reason VARCHAR(1000) NOT NULL, state VARCHAR(12) NOT NULL CHECK(state IN ('DRAFT','APPROVED','REJECTED')), approved_by VARCHAR(160));
CREATE TABLE wf_pay_line (id UUID PRIMARY KEY, period_id UUID NOT NULL REFERENCES wf_period(id), employee_id UUID NOT NULL REFERENCES mfg_employee(id), worked_minutes INTEGER NOT NULL, night_minutes INTEGER NOT NULL, overtime_minutes INTEGER NOT NULL, paid_leave_minutes INTEGER NOT NULL, base_pay NUMERIC(19,4) NOT NULL, night_pay NUMERIC(19,4) NOT NULL, overtime_pay NUMERIC(19,4) NOT NULL, bonus NUMERIC(19,4) NOT NULL, deduction NUMERIC(19,4) NOT NULL, gross NUMERIC(19,4) NOT NULL, payable NUMERIC(19,4) NOT NULL, snapshot TEXT NOT NULL, UNIQUE(period_id,employee_id));
CREATE TABLE wf_audit (id UUID PRIMARY KEY, entity_id UUID NOT NULL, action VARCHAR(80) NOT NULL, actor VARCHAR(160) NOT NULL, notes TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX ix_attendance_employee_time ON wf_attendance(employee_id,starts_at,ends_at);
CREATE INDEX ix_absence_employee_time ON wf_absence(employee_id,starts_at,ends_at);
CREATE INDEX ix_wage_employee_date ON wf_wage(employee_id,effective_from);
